// Model captures only what matters for the domain
struct LoanApplication {
    let id: ApplicationID
    let applicant: Applicant
    var status: ApplicationStatus
    var creditAssessment: CreditAssessment?

    // Domain rule encoded directly in the model
    func canBeApproved() -> Bool {
        guard let assessment = creditAssessment else { return false }
        return assessment.score >= Policy.minimumCreditScore
    }
}

// Entity: identity is the load-bearing part
struct Customer: Equatable {
    let id: CustomerID   // unique, stable identity
    var name: String     // mutable — can change
    var email: String    // mutable — can change
    var address: Address // mutable — can change

    // Equality is identity-based, not attribute-based
    static func == (lhs: Customer, rhs: Customer) -> Bool {
        lhs.id == rhs.id
    }
}

// Attributes describe current state — chosen deliberately
struct Invoice {
    let id: InvoiceID
    let issuedAt: Date          // when the invoice was created
    let dueDate: Date           // payment deadline
    var amountDue: Money        // can change if credits applied
    var status: InvoiceStatus   // PENDING, PAID, OVERDUE, CANCELLED
    // Note: customer name NOT here — fetched via CustomerID reference
    let customerId: CustomerID
}

// Unidirectional relationship — traverse from Order to Customer
// (not from Customer back to all Orders — that's the repository's job)
struct Order {
    let id: OrderID
    let customerId: CustomerID   // reference by ID, not object graph
    var lines: [OrderLine]
    var shippingAddress: Address
}

// Business logic lives in the domain, not the controller
struct Subscription {
    let plan: Plan
    let startDate: Date
    var status: SubscriptionStatus

    // Business rule: can only upgrade, not downgrade mid-cycle
    func canChangeTo(_ newPlan: Plan) -> Bool {
        status == .active && newPlan.tier > plan.tier
    }

    // Business rule: prorated credit calculated here
    func proratedCreditFor(cancellationDate: Date) -> Money {
        let daysRemaining = plan.billingCycle.daysRemaining(from: cancellationDate)
        return plan.dailyRate * Decimal(daysRemaining)
    }
}

// Use case: thin coordinator — orchestrates, does not decide
struct ApproveLeaveRequestUseCase {
    let leaveRepository: LeaveRequestRepository
    let employeeRepository: EmployeeRepository
    let notificationService: NotificationService

    func execute(requestId: LeaveRequestID, approverId: EmployeeID) throws {
        var request = try leaveRepository.find(requestId)
        let approver = try employeeRepository.find(approverId)
        // Domain logic lives in the entity, not here
        try request.approve(by: approver)
        leaveRepository.save(request)
        notificationService.sendApprovalNotification(to: request.employeeId)
    }
}

// Workflow as typed state transitions — impossible states unrepresentable
enum LoanApplicationState {
    case submitted(application: LoanApplication)
    case creditChecked(application: LoanApplication, score: CreditScore)
    case underwritten(application: LoanApplication, assessment: Underwriting)
    case offered(offer: LoanOffer)
    case accepted(offer: LoanOffer, signature: Signature)
    case disbursed(loan: ActiveLoan)
    case rejected(reason: RejectionReason)
}

// Walking skeleton: every layer wired, no real domain logic yet

// Domain (exists but minimal)
struct Order: Identifiable {
    let id: UUID
    let reference: String
}

// Application layer (orchestrates)
struct CreateOrderUseCase {
    let repository: OrderRepository
    func execute(reference: String) throws -> Order {
        let order = Order(id: UUID(), reference: reference)
        try repository.save(order)
        return order
    }
}

// Infrastructure (in-memory stub for skeleton)
final class InMemoryOrderRepository: OrderRepository {
    private var store: [UUID: Order] = [:]
    func save(_ order: Order) throws { store[order.id] = order }
    func find(_ id: UUID) throws -> Order? { store[id] }
}
