// Business rule encoded as an aggregate invariant
extension Order {
    mutating func addLine(_ line: OrderLine) throws {
        // Business rule: cannot add lines to a confirmed or cancelled order
        guard status == .draft else {
            throw OrderError.cannotModifyNonDraftOrder(status)
        }
        // Business rule: order total cannot exceed customer credit limit
        let newTotal = lines.reduce(Money.zero) { $0 + $1.subtotal } + line.subtotal
        guard newTotal <= customer.creditLimit else {
            throw OrderError.exceedsCreditLimit(limit: customer.creditLimit, attempted: newTotal)
        }
        lines.append(line)
    }
}

