// Rich domain model — behaviour lives with the data
struct BankAccount {
    let id: AccountID
    private(set) var balance: Money
    private(set) var status: AccountStatus

    // Domain rule enforced here, not in a service
    mutating func withdraw(_ amount: Money) throws {
        guard status == .active else {
            throw AccountError.accountNotActive
        }
        guard amount <= balance else {
            throw AccountError.insufficientFunds(available: balance, requested: amount)
        }
        balance -= amount
    }
}

// Tactical design building blocks inside a bounded context

// Value Object — equality by attributes, immutable
struct Money: Equatable {
    let amount: Decimal
    let currency: Currency
    static func == (lhs: Money, rhs: Money) -> Bool {
        lhs.amount == rhs.amount && lhs.currency == rhs.currency
    }
}

// Entity — equality by identity, mutable state
struct Product {
