// Cohesive mechanism: algorithmic complexity behind an intention-revealing interface
protocol SchedulingMechanism {
    func earliestSlot(duration: TimeInterval, constraints: [SchedulingConstraint]) -> TimeSlot?
    func optimalSequence(tasks: [Task], deadline: Date) -> [Task]
}

// Domain entity calls the mechanism — stays expressive
struct ServiceOrder {
    let orderId: OrderID
    let requiredDuration: TimeInterval

    func schedule(using scheduler: SchedulingMechanism, deadline: Date) throws -> Appointment {
        guard let slot = scheduler.earliestSlot(
            duration: requiredDuration,
            constraints: self.constraints()
        ) else {
            throw SchedulingError.noSlotAvailable
        }
        return Appointment(orderId: orderId, slot: slot)
    }
}
